/** Current evidence for the frozen server-result contract. Never changes a qualification or resolves an effect. */
public final class CompletionTracker {
    public static final long STABLE_TICKS = 20, MAX_SAMPLE_GAP = 10;
    public enum Condition {
        BODY_DISABLED, WORLD_RECORDS, OLD_EPOCH_REJECTED, RECOVERY_TASKS,
        REBUILD_ENTRYPOINTS, SAVE_QUALIFICATION, TRACKING, SERVER_PRESENCE, NO_PENDING_WORK
    }
    public enum State { MISSING, VERIFIED, FAILED }
    public record Scope(UUID commandId, String authorityHash, SubjectQualification qualification,
                        long activePolicy, long configuredPolicy, String contract) {
        public Scope(UUID commandId,String authorityHash,SubjectQualification qualification,long activePolicy,long configuredPolicy) {
            this(commandId,authorityHash,qualification,activePolicy,configuredPolicy,"ronova:terminal-server/v4");
        }
        public Scope {
            Objects.requireNonNull(commandId); Objects.requireNonNull(authorityHash); Objects.requireNonNull(qualification);
            Objects.requireNonNull(contract);
            if(contract.isBlank()||contract.length()>128)throw new IllegalArgumentException("invalid completion contract");
            if (!qualification.terminal() || activePolicy < 1 || configuredPolicy < 1)
                throw new IllegalArgumentException("invalid completion scope");
        }
        public static Scope of(TerminalOperationPlan plan) {
            return new Scope(plan.commandId(), plan.authorityHash(), plan.qualification(),
                plan.activePolicyRevision(), plan.configuredPolicyRevision(),plan.completionContract());
        }
    }
    public record Evidence(State state, long dependencyRevision, String reference) {
        public Evidence {
            Objects.requireNonNull(state); Objects.requireNonNull(reference);
            if (dependencyRevision < 0 || reference.isBlank() || reference.length() > 128
                || state == State.VERIFIED && dependencyRevision == 0)
                throw new IllegalArgumentException("invalid completion evidence");
        }
    }
    public record Evaluation(Scope scope, long revision, boolean complete, boolean fenced,
                             Set<Condition> missing, long stableTicks, boolean unresolvedEffect) {
        public Evaluation { missing = Set.copyOf(missing); }
    }
    private Scope scope;
    private Map<Condition, Evidence> previous = Map.of();
    private long sampledAt = -1, stableSince = -1, revision;
    private Evaluation current, lastSatisfied;

    public synchronized Evaluation sample(Scope next, long now, Map<Condition, Evidence> evidence,
                                          boolean authorityCurrent, boolean effectsResolved) {
        Objects.requireNonNull(next); Objects.requireNonNull(evidence);
        if (now < 0) throw new IllegalArgumentException("negative observation time");
        EnumMap<Condition, Evidence> snapshot = new EnumMap<>(Condition.class);
        evidence.forEach((key, value) -> snapshot.put(Objects.requireNonNull(key), Objects.requireNonNull(value)));
        EnumSet<Condition> missing = EnumSet.allOf(Condition.class);
        snapshot.forEach((condition, proof) -> { if (proof.state() == State.VERIFIED) missing.remove(condition); });
        boolean fenced = !authorityCurrent || snapshot.values().stream().anyMatch(e -> e.state() == State.FAILED);
        boolean changed = !next.equals(scope) || !snapshot.equals(previous);
        boolean gap = sampledAt < 0 || now < sampledAt || now - sampledAt > MAX_SAMPLE_GAP;
        boolean eligible = !fenced && missing.isEmpty() && effectsResolved;
        if (!eligible) stableSince = -1;
        else if (changed || gap || stableSince < 0) stableSince = now;
        long stable = stableSince < 0 ? 0 : now - stableSince;
        boolean complete = eligible && stable >= STABLE_TICKS;
        if (current == null || changed || gap || current.complete() != complete || current.fenced() != fenced
            || current.unresolvedEffect() == effectsResolved || !current.missing().equals(missing)) revision = Math.addExact(revision, 1);
        scope = next; previous = Map.copyOf(snapshot); sampledAt = now;
        current = new Evaluation(scope, revision, complete, fenced, missing, stable, !effectsResolved);
        if (complete) lastSatisfied = current;
        return current;
    }

    /** A silent observer cannot leave a previously valid certificate displayed forever. */
    public synchronized Evaluation current(long now) {
        if (current == null) return null;
        if (now < sampledAt || now - sampledAt > MAX_SAMPLE_GAP) {
            stableSince = -1;
            if (!current.fenced() || current.complete() || !current.missing().equals(Set.of(Condition.values()))) {
                revision = Math.addExact(revision, 1);
                current = new Evaluation(scope, revision, false, true, Set.of(Condition.values()), 0, current.unresolvedEffect());
            }
            // Invalidate the dependency snapshot too; renewed observations start a fresh window.
            previous = Map.of();
        }
        return current;
    }
    public synchronized Evaluation lastSatisfied() { return lastSatisfied; }

/** Short-lived, thread-confined permission for one exact Root plan. Never grants Root authority. */
public final class PlanExecutionLease implements AutoCloseable {
    public static final long MAX_DURATION_NANOS = 5_000_000_000L;
    private final TerminalOperationPlan plan;
    private final Thread owner = Thread.currentThread();
    private final LongSupplier clock;
    private final long issued, duration;
    private boolean closed;

    public PlanExecutionLease(TerminalOperationPlan plan, LongSupplier clock, long duration) {
        this.plan = Objects.requireNonNull(plan);
        this.clock = Objects.requireNonNull(clock);
        if (duration <= 0 || duration > MAX_DURATION_NANOS) throw new IllegalArgumentException("invalid lease duration");
        this.duration = duration;
        issued = clock.getAsLong();
    }

    public boolean valid(TerminalOperationPlan expected) {
        if (Thread.currentThread() != owner || closed || !plan.equals(expected)) return false;
        long elapsed = clock.getAsLong() - issued;
        return elapsed >= 0 && elapsed < duration;
    }

    @Override public void close() {
        if (Thread.currentThread() != owner) throw new IllegalStateException("lease belongs to another execution thread");
        closed = true;
    }

/** Fixed ordered plan runner; ports cannot renew a stale Root plan or choose another effect identity. */
public final class OperationPlanRunner {
    public interface Ports {
        boolean current(TerminalOperationPlan plan);
        OperationReport.StepReceipt controlled(TerminalOperationPlan plan, TerminalOperationPlan.Step step);
        default OperationReport.StepReceipt controlled(TerminalOperationPlan plan, TerminalOperationPlan.Step step,
            BooleanSupplier permitted) {
            return permitted.getAsBoolean() ? controlled(plan, step)
                : new OperationReport.StepReceipt(step, OperationReport.Status.FENCED, "final-write-permission-expired");
        }
        EffectClaim prepare(TerminalOperationPlan plan);
        boolean enter(EffectClaim claim);
        void opaque(TerminalOperationPlan plan);
        default void opaque(TerminalOperationPlan plan, BooleanSupplier permitted) {
            if (permitted.getAsBoolean()) opaque(plan);
        }
        void finishUnknown(EffectClaim claim);
    }
    private final ThreadLocal<Set<String>> active = ThreadLocal.withInitial(HashSet::new);
    private final LongSupplier clock;
    public OperationPlanRunner() { this(System::nanoTime); }
    OperationPlanRunner(LongSupplier clock) { this.clock = Objects.requireNonNull(clock); }
    public OperationReport run(TerminalOperationPlan plan, Ports ports) {
        Objects.requireNonNull(plan); Objects.requireNonNull(ports);
        Set<String> stack = active.get();
        String cause = plan.commandId() + "/" + plan.subjectKey().canonical();
        if (!stack.add(cause)) return new OperationReport(plan, List.of(), false, false, "REENTRANT");
        List<OperationReport.StepReceipt> receipts = new ArrayList<>(); boolean entered = false, scopedFailure = false;
        try (var lease = new PlanExecutionLease(plan, clock, PlanExecutionLease.MAX_DURATION_NANOS)) {
            for (var step : plan.orderedSteps()) {
                if (!lease.valid(plan) || !ports.current(plan)) {
                    receipts.add(new OperationReport.StepReceipt(step, OperationReport.Status.FENCED, "qualification-or-plan-revision-changed"));
                    return new OperationReport(plan, receipts, entered, false, "FENCED");
                }
                if (step == TerminalOperationPlan.Step.TERMINAL_LIFECYCLE) {
                    EffectClaim claim = ports.prepare(plan);
                    if (claim.granted()) {
                        if (!claim.record().key().equals(plan.effectKey())) throw new IllegalStateException("Root returned a different semantic effect key");
                        try {
                            if (lease.valid(plan) && ports.current(plan) && ports.enter(claim)) {
                                // Entering the durable claim can itself invalidate the execution context.
                                if (lease.valid(plan) && ports.current(plan)) {
                                    entered = true;
                                    ports.opaque(plan, () -> lease.valid(plan) && ports.current(plan));
                                }
                            }
                        } catch (RuntimeException failed) {
                            // A callback exception cannot prove absence of its physical effects.
                        } finally { ports.finishUnknown(claim); }
                    }
                    boolean unresolved = claim.record() != null || claim.status() == EffectClaim.Status.LEGACY_CLAIM_UNKNOWN;
                    receipts.add(new OperationReport.StepReceipt(step, unresolved ? OperationReport.Status.EFFECT_UNKNOWN : OperationReport.Status.FENCED,
                        "root-effect-claim:" + claim.status()));
                    if (!unresolved) scopedFailure = true;
                } else {
                    OperationReport.StepReceipt result;
                    try { result = Objects.requireNonNull(ports.controlled(plan, step, () -> lease.valid(plan) && ports.current(plan))); }
                    catch (RuntimeException failed) { result = new OperationReport.StepReceipt(step, OperationReport.Status.UNAVAILABLE, failed.getClass().getSimpleName()); }
                    if (result.step() != step) throw new IllegalStateException("executor returned another step receipt");
                    receipts.add(result);
                    if (result.status() == OperationReport.Status.FENCED || result.status() == OperationReport.Status.UNAVAILABLE) {
                        scopedFailure = true;
                        if (step == TerminalOperationPlan.Step.ADMISSION_FENCE || step == TerminalOperationPlan.Step.SERVER_PRESENCE)
                            return new OperationReport(plan, receipts, entered, false, "FENCED");
                    }
                }
                if (!lease.valid(plan) || !ports.current(plan)) {
                    // Preserve EFFECT_UNKNOWN: revocation cannot erase an effect already attempted.
                    return new OperationReport(plan, receipts, entered, false, "FENCED");
                }
            }
            return new OperationReport(plan, receipts, entered, false, scopedFailure ? "FENCED" : "PARTIAL");
        } finally { stack.remove(cause); if (stack.isEmpty()) active.remove(); }
    }

/** Derived by the existing Root writer from one retained, committed qualification receipt. */
public record TerminalOperationPlan(UUID planId, long planRevision, UUID commandId, String authorityHash,
    long authorityCommitIndex, SubjectQualification qualification, long activePolicyRevision,
    long configuredPolicyRevision, String ownerIdentity, String completionContract,
    List<Step> orderedSteps, Set<RuntimeSurface> requiredSurfaces, Set<RuntimeSurface> optionalSurfaces,
    long reservedHeapBytes, String recoveryPolicy) {
    public enum Step { ADMISSION_FENCE, SERVER_PRESENCE, SOURCE_QUALIFICATION, TERMINAL_LIFECYCLE, TERMINAL_STATE, WORLD_RECORDS, NETWORK_PROJECTION }
    public TerminalOperationPlan {
        Objects.requireNonNull(planId); Objects.requireNonNull(commandId); Objects.requireNonNull(qualification);
        authorityHash = EffectRecord.checkedHash(authorityHash);
        if (planRevision < authorityCommitIndex || !planId.equals(commandId) || authorityCommitIndex < 1 || !qualification.terminal()
            || qualification.revisions() == null || qualification.revisions().activeIncarnation() == null
            || activePolicyRevision < 1 || configuredPolicyRevision < 1 || reservedHeapBytes != 16384)
            throw new IllegalArgumentException("invalid terminal operation plan");
        orderedSteps = List.copyOf(orderedSteps); requiredSurfaces = Set.copyOf(requiredSurfaces); optionalSurfaces = Set.copyOf(optionalSurfaces);
        if (!orderedSteps.equals(List.of(Step.values()))
            || !requiredSurfaces.equals(Set.of(RuntimeSurface.REGISTRY, RuntimeSurface.TEMPORAL, RuntimeSurface.DATA))
            || !optionalSurfaces.equals(Set.of(RuntimeSurface.NETWORK, RuntimeSurface.PRESENTATION))
            || !Objects.equals(ownerIdentity, "root/" + qualification.subjectKey().realmId().canonical())
            || !Objects.equals(completionContract, "ronova:terminal-server/v4")
            || !Objects.equals(recoveryPolicy, "CONTROLLED_REASSERT_OPAQUE_NO_REPLAY"))
            throw new IllegalArgumentException("unregistered plan contract");
    }
    public static TerminalOperationPlan terminal(UUID command, String hash, long index, long planRevision,
        SubjectQualification qualification, long activePolicy, long configuredPolicy) {
        return new TerminalOperationPlan(command, planRevision, command, hash, index, qualification, activePolicy, configuredPolicy,
            "root/" + qualification.subjectKey().realmId().canonical(), "ronova:terminal-server/v4", List.of(Step.values()),
            Set.of(RuntimeSurface.REGISTRY, RuntimeSurface.TEMPORAL, RuntimeSurface.DATA),
            Set.of(RuntimeSurface.NETWORK, RuntimeSurface.PRESENTATION), 16384, "CONTROLLED_REASSERT_OPAQUE_NO_REPLAY");
    }
    public SubjectKey subjectKey() { return qualification.subjectKey(); }
    public UUID physicalNonce() { return qualification.revisions().activeIncarnation().nonce(); }
    public EffectKey effectKey() { return new EffectKey(commandId, qualification.targetEpoch(), EffectRecord.TERMINAL_LIFECYCLE, EffectRecord.ONCE_SLOT); }
    public String causalityKey() { return commandId + "/" + subjectKey().canonical() + ":" + qualification.targetEpoch().generation() + "/" + planRevision; }
}

