                verified?MechanismLevel.PROTECT_RONOVA:MechanismLevel.OFF,verified?EvidenceState.VERIFIED:EvidenceState.UNOBSERVED,
                verified?ActivationState.ACTIVE:ActivationState.UNAVAILABLE);
        }
        return result;
    }
}

