/** Connects measured support to policy presentation without granting new attack permissions. */
public final class RuntimeCapabilityProjection {
    private RuntimeCapabilityProjection() {}
    public static StrengthPolicySnapshot apply(StrengthPolicySnapshot policy,EnforcementProof enforcement,CodeIntegrityProof code) {
        var result=policy;
        for(var key:Set.of(StrengthOptionKey.PROTECT_CODE_INTEGRITY,StrengthOptionKey.RUNTIME_CRITICAL_CLASS_WATCH,
            StrengthOptionKey.INTERCEPT_INSTRUMENTATION)) {
            result=result.withCapability(key,code.supported()?MechanismLevel.PROTECT_RONOVA:MechanismLevel.OFF,
                code.current()?MechanismLevel.PROTECT_RONOVA:MechanismLevel.OFF,
                code.current()?EvidenceState.VERIFIED:code.supported()?EvidenceState.FAILED:EvidenceState.UNOBSERVED,
                code.current()?ActivationState.ACTIVE:code.supported()?ActivationState.FENCED:ActivationState.UNAVAILABLE);
        }
        for(var key:Set.of(StrengthOptionKey.RUNTIME_JVMTI,StrengthOptionKey.RUNTIME_NATIVE,StrengthOptionKey.RUNTIME_BACKGROUND_INTEGRITY)) {
            boolean verified=enforcement.current();
            result=result.withCapability(key,enforcement.supported()?MechanismLevel.PROTECT_RONOVA:MechanismLevel.OFF,
                verified?MechanismLevel.PROTECT_RONOVA:MechanismLevel.OFF,verified?EvidenceState.VERIFIED:EvidenceState.UNOBSERVED,
                verified?ActivationState.ACTIVE:ActivationState.UNAVAILABLE);
        }
        return result;
    }
}

