        VERIFIED,
        MIRRORED,
        RECEIPT_MIRRORED,
        REALM_MISMATCH,
        ROLLBACK_REJECTED,
        STATE_CONFLICT,
        RECEIPT_DRIFT,
        READ_ONLY,
        FAILPOINT,
        INVALID_INPUT
    }
}

