import java.io.*;
import java.security.*;
import java.util.HexFormat;

/** Bounded digest of bytes accepted by the actual compressed output stream, not a commit receipt. */
public final class SavedDataEncodedWrite implements AutoCloseable {
    private static final ThreadLocal<SavedDataEncodedWrite> CURRENT=new ThreadLocal<>();
    private final SavedDataEncodedWrite previous;
    private final SavedDataSaveTrace trace;
    private final long generation;
    private Object image;
    private Object holder;
    private final Thread owner=Thread.currentThread();
    private final MessageDigest digest;
    private final NbtWriteReferences references;
    private boolean bound,closed,successful;
    private volatile boolean invalid;
    private long bytes;
    private String fileIdentity;
    private boolean fileIdentityConfirmed;
    private SavedDataEncodedWrite(SavedDataSaveTrace trace,Object image,Object holder) {
        this.trace=trace;this.image=image;this.holder=holder;references=new NbtWriteReferences(image);generation=trace.snapshot().generation();previous=CURRENT.get();
        if(previous!=null)previous.invalid=true;
        try {digest=MessageDigest.getInstance("SHA-256");} catch(NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}
        CURRENT.set(this);
    }
    public static SavedDataEncodedWrite open(SavedDataSaveTrace trace,Object image){return open(trace,image,null);}
    public static SavedDataEncodedWrite open(SavedDataSaveTrace trace,Object image,Object holder){return trace==null?null:new SavedDataEncodedWrite(trace,image,holder);}
    public static AutoCloseable enterReference(Object parent,net.minecraft.nbt.Tag child,String key) {
        var capture=CURRENT.get();if(capture==null||capture.invalid||capture.closed)return null;
        Class<?> type=child==null?null:child.getClass();
        boolean compound=type==net.minecraft.nbt.CompoundTag.class;
        boolean supported=compound||type==net.minecraft.nbt.ListTag.class||type==net.minecraft.nbt.ByteTag.class
            ||type==net.minecraft.nbt.ShortTag.class||type==net.minecraft.nbt.IntTag.class||type==net.minecraft.nbt.LongTag.class
            ||type==net.minecraft.nbt.FloatTag.class||type==net.minecraft.nbt.DoubleTag.class||type==net.minecraft.nbt.StringTag.class
            ||type==net.minecraft.nbt.ByteArrayTag.class||type==net.minecraft.nbt.IntArrayTag.class||type==net.minecraft.nbt.LongArrayTag.class;
        return capture.references.enter(parent,child,key,compound,supported);
    }
    public static void leaveReference(AutoCloseable scope) {
        if(scope!=null)try {scope.close();}catch(Exception unavailable){var capture=CURRENT.get();if(capture!=null)capture.invalidate();}
    }
    public static OutputStream observe(Object image,OutputStream stream) {
        var capture=CURRENT.get();
        if(capture==null)return stream;
        if(capture.image!=image||capture.bound||capture.closed){capture.invalid=true;return stream;}
        capture.bound=true;
        // Only the exact JDK stream is supported. Wrappers are not traversed by
        // guessed fields and a synthetic stream can never confer a file identity.
        final FileOutputStream file=stream.getClass()==FileOutputStream.class?(FileOutputStream)stream:null;
        if(file!=null)try {capture.fileIdentity=dev.ronova.coremod.nativebridge.NativeBridge.savedFileIdentity(file.getFD());}
        catch(IOException|RuntimeException|LinkageError unavailable){capture.fileIdentity=null;}
        return new FilterOutputStream(stream) {
            @Override public void write(int value)throws IOException {
                try {out.write(value);}catch(IOException|RuntimeException|Error failure){capture.invalidate();throw failure;}
                synchronized(capture){if(capture.accept(1))capture.digest.update((byte)value);}
            }
            @Override public void write(byte[] value,int offset,int length)throws IOException {
                try {out.write(value,offset,length);}catch(IOException|RuntimeException|Error failure){capture.invalidate();throw failure;}
                synchronized(capture){if(capture.accept(length))capture.digest.update(value,offset,length);}
            }
            @Override public void flush()throws IOException {
                try {out.flush();}catch(IOException|RuntimeException|Error failure){capture.invalidate();throw failure;}
            }
            @Override public void close()throws IOException {
                if(file!=null&&!capture.fileIdentityConfirmed)try {
                    String after=dev.ronova.coremod.nativebridge.NativeBridge.savedFileIdentity(file.getFD());
                    capture.fileIdentityConfirmed=capture.fileIdentity!=null&&capture.fileIdentity.equals(after);
                } catch(IOException|RuntimeException|LinkageError unavailable){capture.fileIdentityConfirmed=false;}
                try {out.close();}catch(IOException|RuntimeException|Error failure){capture.invalidate();throw failure;}
            }
        };
    }
    private synchronized void invalidate(){invalid=true;trace.invalidateEncoded(generation);}
    private boolean accept(int count){
        if(Thread.currentThread()!=owner||closed){invalidate();return false;}
        if(invalid)return false;
        if(count<0||bytes>16L*1024*1024-count){invalid=true;return false;}
        bytes+=count;return true;
    }
    public synchronized void succeeded(){if(Thread.currentThread()!=owner)invalidate();else successful=true;}
    @Override public synchronized void close(){
        if(Thread.currentThread()!=owner){invalidate();return;}
        if(closed)return;closed=true;
        if(CURRENT.get()!=this){invalid=true;releaseReferences();return;}
        var restore=previous;while(restore!=null&&restore.closed)restore=restore.previous;
        if(restore==null)CURRENT.remove();else CURRENT.set(restore);
        try {if(successful&&bound&&!invalid) {
            var encoded=trace.encoded(generation,HexFormat.of().formatHex(digest.digest()),bytes,references.snapshot(),
                fileIdentityConfirmed?fileIdentity:null);
            try {
                if(encoded!=null&&holder instanceof net.minecraft.world.level.saveddata.SavedData data)
                    dev.ronova.coremod.bootstrap.ServerRuntimeRegistry.savedDataEncoded(data,encoded);
            } catch(RuntimeException|LinkageError unavailable) {
                // Absence of a source confirmation must not suppress the original save.
            } finally {java.lang.ref.Reference.reachabilityFence(image);}
        }} finally {releaseReferences();}
    }
    private void releaseReferences(){references.release();image=null;holder=null;}
}

package dev.ronova.coremod.observation;

import java.util.ArrayDeque;
import java.util.Objects;
import java.util.function.BiPredicate;
import java.util.function.BooleanSupplier;
import java.util.function.Supplier;

/** Reserve result retention before starting a mutation; retry only the receipt, never the mutation. */
final class DeferredReceiptBuffer<K, V> implements AutoCloseable {
    private final int capacity;
    private final Supplier<Runnable> reserve;
    private final ArrayDeque<Ticket> rotation = new ArrayDeque<>();
    private boolean closed;
    DeferredReceiptBuffer(int capacity, Supplier<Runnable> reserve) {
        if (capacity < 1) throw new IllegalArgumentException("invalid receipt capacity");
        this.capacity = capacity; this.reserve = Objects.requireNonNull(reserve);
    }
    final class Ticket implements AutoCloseable {
        final K key;
        private final Runnable release;
        private V result;
        private boolean released;
        private Ticket(K key, Runnable release) { this.key = key; this.release = release; }
        void complete(V result) {
            synchronized (DeferredReceiptBuffer.this) {
                if (released) return; // Shutdown preserves the pre-existing durable unknown intent.
                if (this.result != null) throw new IllegalStateException("receipt already completed");
                this.result = Objects.requireNonNull(result);
            }
        }
        @Override public void close() {
            synchronized (DeferredReceiptBuffer.this) {
                if (released) return;
                released = true; rotation.remove(this); release.run();
            }
        }
    }
    synchronized Ticket reserve(K key) {
        Objects.requireNonNull(key);
        if (closed || rotation.size() >= capacity) return null;
        Runnable release = reserve.get();
        if (release == null) return null;
        var ticket = new Ticket(key, release); rotation.addLast(ticket); return ticket;
    }
    synchronized int flush(int limit, BooleanSupplier budget, BiPredicate<K, V> publish) {
        if (closed || limit < 1) return 0;
        int visited = rotation.size(), attempted = 0;
        while (visited-- > 0 && attempted < limit && !rotation.isEmpty()) {
            var ticket = rotation.removeFirst(); rotation.addLast(ticket);
            if (ticket.result == null) continue;
            if (!budget.getAsBoolean()) break;
            attempted++;
            boolean accepted;
            try { accepted = publish.test(ticket.key, ticket.result); }
            catch (RuntimeException | LinkageError unavailable) { accepted = false; }
            if (accepted) ticket.close();
        }
        return attempted;
    }
    synchronized int size() { return rotation.size(); }
    /** A shutdown snapshot includes only already-completed work. Failure retains every ticket. */
    synchronized boolean flushBatch(java.util.function.Predicate<java.util.List<java.util.Map.Entry<K, V>>> publish) {
        if (closed) return false;
        var ready = rotation.stream().filter(ticket -> ticket.result != null).toList();
        if (ready.isEmpty()) return true;
        var values = ready.stream().map(ticket -> java.util.Map.entry(ticket.key, ticket.result)).toList();
        boolean accepted;
        try { accepted = publish.test(values); }
        catch (RuntimeException | LinkageError unavailable) { accepted = false; }
        if (!accepted) return false;
        RuntimeException failure = null;
        for (var ticket : ready) try { ticket.close(); }
        catch (RuntimeException error) {
            if (failure == null) failure = error; else if (failure != error) failure.addSuppressed(error);
        }
        if (failure != null) throw failure;
        return true;
    }
    synchronized int readyCount() { return (int) rotation.stream().filter(ticket -> ticket.result != null).count(); }
    synchronized boolean anyKey(java.util.function.Predicate<K> predicate) {
        return rotation.stream().anyMatch(ticket -> predicate.test(ticket.key));
    }
    @Override public synchronized void close() {
        if (closed) return; closed = true;
        RuntimeException failure = null;
        while (!rotation.isEmpty()) {
            try { rotation.peekFirst().close(); }
            catch (RuntimeException error) {
                if (failure == null) failure = error; else if (failure != error) failure.addSuppressed(error);
            }
        }
        if (failure != null) throw failure;
    }
}

package dev.ronova.coremod.observation;

import dev.ronova.coremod.root.api.*;
import java.util.Objects;
import java.util.function.Function;

/** Query one acknowledged original intent. No new intent, write permission or completion fact is created. */
public final class RecoveryStorageReadbackQuery {
    private RecoveryStorageReadbackQuery() {}
    public static RecoveryFileReadback.Result query(EffectKey key,
        Function<EffectKey,RecoveryWorkResult> lookup,
        Function<RecoveryWorkDescriptor,RecoveryFileReadback.Result> readCurrentBinding) {
        Objects.requireNonNull(lookup);Objects.requireNonNull(readCurrentBinding);
        if(key==null)return unavailable();
        var original=lookup.apply(key);
        if(original==null||!key.equals(original.record().key())
            ||original.descriptor().kind()!=RecoveryWorkDescriptor.Kind.STORAGE_COMMIT)return unavailable();
        var observed=readCurrentBinding.apply(original.descriptor());
        // ACK loss, replacement of the original record, or a concurrent result update requires a fresh query.
        if(observed==null||!original.equals(lookup.apply(key)))return unavailable();
        if(observed.status()==RecoveryFileReadback.Status.OBSERVED_MATCH
            &&(!original.descriptor().expectedHash().equals(observed.observedHash())
                ||observed.reason()!=RecoveryFileReadback.Reason.NONE||observed.bytes()<0
                ||observed.fileIdentity()==null||observed.fileIdentity().isEmpty()
                ||!original.descriptor().fileIdentity().isEmpty()&&!original.descriptor().fileIdentity().equals(observed.fileIdentity())))return unavailable();
        return observed;
    }
    private static RecoveryFileReadback.Result unavailable() {
        return new RecoveryFileReadback.Result(RecoveryFileReadback.Status.UNAVAILABLE,
            RecoveryFileReadback.Reason.PRECONDITION_UNPROVEN,0,null);
    }
}

package dev.ronova.coremod.observation;

import java.util.Objects;

/** Consecutive, already receiver-verified events for one task. Never spans another
 * task, a copy event, a different parent/scheduler, or a changed proof generation.
 * Only exactly paired exits become completed counts; one open token is retained. */
final class TaskEventRun {
    final Object task,parent;
    final long changes,dropped;
    Object scheduler;
    long completed,submissions,execution,events=1;
    boolean running=true,hasScheduler;
    TaskEventRun(Object task,Object parent,long execution,long changes,long dropped) {
        this.task=Objects.requireNonNull(task);this.parent=parent==task?null:parent;
        if(execution<1)throw new IllegalArgumentException("invalid execution token");
        this.execution=execution;this.changes=changes;this.dropped=dropped;
    }
    boolean append(int kind,Object task,Object scheduler,Object parent,long token,long changes,long dropped) {
        if(this.task!=task||this.parent!=(parent==task?null:parent)||this.changes!=changes||this.dropped!=dropped||events==Long.MAX_VALUE)return false;
        if(kind==1) {
            if(running||token<=execution)return false;
            execution=token;running=true;
        } else if(kind==2) {
            if(!running||token!=execution||completed==Long.MAX_VALUE)return false;
            completed++;running=false;
        } else if(kind==3) {
            if(token!=0||submissions==Long.MAX_VALUE||hasScheduler&&this.scheduler!=scheduler)return false;
            this.scheduler=scheduler;hasScheduler=true;submissions++;
        } else return false;
        events++;return true;
    }
    void mergeInto(TaskExecutionGraph graph) {
        graph.observedCompletedRun(task,scheduler,parent,completed,submissions);
        if(running)graph.entered(task,execution,parent);
    }
}

